// Why Code: parsarea unui update Telegram (mesaj sau buton) + whitelist de chat-uri; nodurile native nu extrag comanda și argumentele.
const u = $input.first().json ?? {};
const allowed = String($env.TG_BROKER_CHAT_IDS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
const cb = u.callback_query;
const msg = cb ? cb.message : u.message;
const chatId = String(msg?.chat?.id ?? '');
const out = (o) => [{ json: { chatId, callbackId: cb?.id ?? '', claimId: '', question: '', hint: '', ...o } }];

// Doar chat-urile brokerilor (TG_BROKER_CHAT_IDS); restul sunt ignorate fără niciun răspuns.
if (!chatId || !allowed.includes(chatId)) return out({ kind: 'ignore' });

if (cb) {
  const m = /^(take|ask):([0-9a-f-]{36})$/i.exec(String(cb.data ?? ''));
  return m ? out({ kind: m[1].toLowerCase(), claimId: m[2].toLowerCase() }) : out({ kind: 'ignore' });
}

const text = String(msg?.text ?? '').trim();
const c = /^\/(\w+)(?:@\w+)?(?:\s+([\s\S]*))?$/.exec(text);
if (!c) return out({ kind: 'help' });
const cmd = c[1].toLowerCase();
const arg = String(c[2] ?? '').trim();
if (cmd === 'dosare') return out({ kind: 'dosare' });
if (cmd === 'intreaba') {
  return arg ? out({ kind: 'intreaba', question: arg.slice(0, 600) }) : out({ kind: 'help', hint: 'Scrie întrebarea după comandă, de exemplu: /intreaba ce acoperă CASCO la furtul de oglinzi?' });
}
if (cmd === 'urgent' || cmd === 'digest') return out({ kind: 'help', hint: `/${cmd} nu e disponibilă încă.` });
return out({ kind: 'help' });

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Why Code: textul de răspuns în română, în funcție de rezultatul funcției broker_take_claim (mai multe cazuri); niciun nod nativ nu compune textul.
const p = $('Parse update').first().json;
const r = $input.first().json ?? {};
const errors = {
  not_found: '⚠️ Nu găsesc dosarul.',
  taken: `⚠️ Dosarul ${esc(r.ref)} e deja preluat de alt broker.`,
  closed: `ℹ️ Dosarul ${esc(r.ref)} e închis.`,
  not_ready: `ℹ️ Dosarul ${esc(r.ref)} nu e încă trimis de clienți (lipsesc semnăturile sau datele).`,
};
let text;
if (r.error && r.ok === undefined) text = '⚠️ Nu am putut prelua dosarul acum. Încearcă din nou sau deschide-l în dashboard.';
else if (r.ok === false) text = errors[r.error] ?? '⚠️ Nu am putut prelua dosarul.';
else if (r.already) text = `ℹ️ Dosarul <b>${esc(r.ref)}</b> e deja în lucru.`;
else {
  text = `✅ Ai preluat dosarul <b>${esc(r.ref)}</b>. Status: în lucru.`;
  if (r.handoffs > 0) text += `\nConversațiile legate de dosar au trecut la tine; AI-ul nu mai răspunde acolo.`;
  if (!r.assigned) text += `\n(Chatul nu e legat de un broker în baza de date, deci dosarul nu are broker asignat.)`;
}
return [{ json: { chatId: p.chatId, text } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Why Code: lista de lipsuri normalizată (șiruri sau {label}) + un mesaj-draft pentru client; logica pe mai multe cazuri.
const p = $('Parse update').first().json;
let rows = [];
try { rows = JSON.parse($input.first().json.data || '[]'); } catch { rows = []; }
const c = Array.isArray(rows) ? rows[0] : null;
if (!c) return [{ json: { chatId: p.chatId, text: '⚠️ Nu găsesc dosarul.', claimId: null, missing: [] } }];

const missing = (Array.isArray(c.missing_items) ? c.missing_items : []).map((m) => (typeof m === 'string' ? m : m?.label)).filter(Boolean);
let text;
if (missing.length === 0) {
  text = `✅ La dosarul <b>${esc(c.public_ref)}</b> nu lipsește nimic.`;
} else {
  const list = missing.map((m) => `• ${esc(m)}`).join('\n');
  // Etichetele din dashboard sunt constatări („Nicio poză…”, „Lipsește semnătura…”); clientului îi trebuie o cerere, deci le transformăm în „ce ne trebuie”.
  const asks = [
    [/Datele șoferului (\w)/i, (m) => `datele șoferului ${m[1]}`],
    [/Actele șoferului (\w)/i, (m) => `actele șoferului ${m[1]} (talon, permis, poliță)`],
    [/Șoferul (\w) nu a bifat circumstan/i, (m) => `circumstanțele bifate de șoferul ${m[1]}`],
    [/Zona lovită a vehiculului (\w)/i, (m) => `zona lovită a vehiculului ${m[1]}`],
    [/semnătura șoferului (\w)/i, (m) => `semnătura șoferului ${m[1]}`],
    [/poză cu daunele vehiculului (\w)/i, (m) => `poze cu daunele vehiculului ${m[1]}`],
    [/schi[țt]a/i, () => 'schița accidentului'],
  ];
  const phrase = (label) => { for (const [re, f] of asks) { const m = re.exec(label); if (m) return f(m); } return label.charAt(0).toLowerCase() + label.slice(1); };
  const items = missing.map(phrase);
  const joined = items.length > 1 ? `${items.slice(0, -1).join(', ')} și ${items[items.length - 1]}` : items[0];
  const draft = `Bună ziua! Pentru dosarul ${c.public_ref} mai avem nevoie de: ${joined}. Ne puteți ajuta cu aceste informații? Vă mulțumim!`;
  text = `📋 <b>${esc(c.public_ref)}</b>: lipsesc\n${list}\n\nMesaj pentru client (copiază și trimite):\n<i>${esc(draft)}</i>`;
}
return [{ json: { chatId: p.chatId, text, claimId: p.claimId, ref: c.public_ref, missing } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Why Code: formatarea listei de dosare (stare în română, dată în fusul României); nicio combinație de noduri native nu o acoperă curat.
const p = $('Parse update').first().json;
let rows = [];
try { rows = JSON.parse($input.first().json.data || '[]'); } catch { rows = []; }
if (!Array.isArray(rows)) rows = [];
const STATUS = { signed: 'semnat', submitted: 'trimis', in_progress: 'în lucru' };
const when = (iso) => { try { return new Date(iso).toLocaleString('ro-RO', { timeZone: 'Europe/Bucharest', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }); } catch { return ''; } };
const text = rows.length === 0
  ? 'Nu ai dosare deschise.'
  : `<b>Dosare deschise (${rows.length})</b>\n` + rows.map((r) => `• <b>${esc(r.public_ref)}</b> · ${esc(STATUS[r.status] ?? r.status)}${r.accident_at ? ' · ' + esc(when(r.accident_at)) : ''}${r.broker_id ? '' : ' · fără broker'}`).join('\n') + '\n\nPreia un dosar cu butonul „Preiau” din mesajul lui.';
return [{ json: { chatId: p.chatId, text } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Why Code: răspunsul copilotului pentru Telegram: HTML escapat, surse doar dacă lipsesc citările din text, limită de lungime.
const p = $('Parse update').first().json;
const r = $input.first().json ?? {};
let text;
if (r.error || typeof r.answer !== 'string') {
  text = '⚠️ Copilotul nu răspunde acum. Încearcă mai târziu sau folosește pagina Copilot din dashboard.';
} else {
  text = esc(r.answer);
  const srcs = [...new Set((Array.isArray(r.sources) ? r.sources : []).map((s) => s.title + (s.page ? `, pag. ${s.page}` : '')))];
  if (r.found && srcs.length && !/\[[^\]]+\]/.test(r.answer)) text += `\n\n<i>Surse: ${esc(srcs.join('; '))}</i>`;
}
return [{ json: { chatId: p.chatId, text: text.slice(0, 3900) } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Why Code: textul de ajutor cu comenzile disponibile, plus un indiciu opțional (comandă fără argument sau nefinalizată).
const p = $('Parse update').first().json;
const lines = [
  p.hint ? esc(p.hint) + '\n' : null,
  '<b>BrokerPilot Desk</b>',
  '/dosare: dosarele deschise',
  '/intreaba &lt;întrebare&gt;: copilotul (răspunde doar din documente, cu surse)',
  'Butoanele din mesajele despre dosare: „Preiau” și „Cere info lipsă”.',
].filter(Boolean);
return [{ json: { chatId: p.chatId, text: lines.join('\n') } }];
